+const OPERATIONS = {
+  add: (a, b) => a + b,
+  subtract: (a, b) => a - b,
+  multiply: (a, b) => a * b,
+  divide: (a, b) => a / b,
+};
+
+const ALLOWED_FIELDS = ['a', 'b', 'operation'];
+
+function isNumber(value) {
+  return typeof value === 'number' && Number.isFinite(value);
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'calculate',
+      description: 'Perform a basic arithmetic operation on two numbers.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          a: { type: 'number', description: 'The first operand.' },
+          b: { type: 'number', description: 'The second operand.' },
+          operation: {
+            type: 'string',
+            enum: ['add', 'subtract', 'multiply', 'divide'],
+            description: 'The arithmetic operation to perform.',
+          },
+        },
+        required: ['a', 'b', 'operation'],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'calculate') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.includes(key)) {
+      throw new Error(`Unexpected field: ${key}`);
+    }
+  }
+
+  if (!('a' in args)) throw new Error('Missing required field: a');
+  if (!('b' in args)) throw new Error('Missing required field: b');
+  if (!('operation' in args)) throw new Error('Missing required field: operation');
+
+  const { a, b, operation } = args;
+
+  if (!isNumber(a)) throw new Error('Field a must be a number');
+  if (!isNumber(b)) throw new Error('Field b must be a number');
+
+  if (typeof operation !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATIONS, operation)) {
+    throw new Error(`Unsupported operation: ${operation}`);
+  }
+
+  if (operation === 'divide' && b === 0) {
+    throw new Error('Division by zero');
+  }
+
+  const result = OPERATIONS[operation](a, b);
+
+  return {
+    content: [{ type: 'text', text: String(result) }],
+  };
+}
